"""Package reviewable source, requested handover and real covers. No generated build or credentials."""
from pathlib import Path
import hashlib,json,shutil,subprocess,zipfile
from PIL import Image
root=Path(__file__).resolve().parent.parent
out=root/'public/handover';out.mkdir(parents=True,exist_ok=True)
docs=['README.md','QA.md','ASSETS.md','DECISIONS.md','STATE.md','SUBMISSION.md']
for name in docs+[f'cover-{n}.png' for n in range(1,4)]+['relic-run-gameplay.jpg']:
    p=root/name
    assert p.is_file(),name
    if name.endswith('.png'):assert Image.open(p).size==(1800,1200)
    shutil.copyfile(p,out/name)
evidence=out/'evidence';evidence.mkdir(exist_ok=True)
for p in (root/'evidence').glob('*.json'):shutil.copyfile(p,evidence/p.name)
files=subprocess.check_output(['git','ls-files','-co','--exclude-standard','-z'],cwd=root).decode().split('\0')
files=sorted({p for p in files if p and not p.startswith('public/handover/') and (root/p).is_file()})
archive=out/'emberfall-handover.zip'
with zipfile.ZipFile(archive,'w',zipfile.ZIP_DEFLATED,compresslevel=7) as z:
    for p in files:z.write(root/p,'emberfall/'+p)
with zipfile.ZipFile(archive) as z:
    assert z.testzip() is None
    for name in docs+[f'cover-{n}.png' for n in range(1,4)]:assert 'emberfall/'+name in z.namelist()
manifest={'date':'2026-10-29','sourceFiles':len(files),'archive':archive.name,'bytes':archive.stat().st_size,'sha256':hashlib.sha256(archive.read_bytes()).hexdigest(),'unitServiceTestsPassed':34,'adventureInputRuns':1000,'adventureInvalidOrStuckRuns':0,'productionRateBotMatches':1000,'sharedCombat':'blocked: cloud browser supplied zero ICE candidates','cover3':'Actual bot champions, explicitly labelled spectator view; viewer win not claimed'}
(out/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
links=''.join(f'<a class="doc" href="{n}" download><b>{n}</b><span>'+{'README.md':'Play, controls and architecture','QA.md':'Executed tests and open acceptance gates','ASSETS.md':'Original asset and screenshot provenance','DECISIONS.md':'Hosting measurements and design choices','STATE.md':'Current checkpoint and continuation notes','SUBMISSION.md':'Three titles; two exactly counted descriptions'}[n]+'</span></a>' for n in docs)
html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>EMBERFALL · Handover</title><meta name="description" content="EMBERFALL source, genuine gameplay covers and transparent QA evidence."><style>:root{color-scheme:dark;font-family:Arial,Helvetica,sans-serif;color:#eeeedf;background:#0b1c1f}*{box-sizing:border-box}body{margin:0}main{max-width:1140px;margin:auto;padding:56px 28px}a{color:#ffbf7b;text-decoration:none}a:focus-visible{outline:2px solid #ffbf7b;outline-offset:5px}header{border-bottom:1px solid #b5dec32b;padding-bottom:32px}.kicker{letter-spacing:3px;font-size:11px;color:#b5dec3}h1{font-size:clamp(42px,7vw,80px);line-height:1;margin:20px 0;letter-spacing:-2px}h1 em{font-style:normal;color:#ffb56d}p{line-height:1.7;color:#b7c9c0;max-width:880px}.actions{display:flex;flex-wrap:wrap;gap:12px;margin:26px 0 4px}.button{padding:16px 24px;border:1px solid #b5dec340;font-size:12px;font-weight:bold;letter-spacing:1px}.primary{background:#ffb56d;color:#142a29;border-color:#ffb56d}.verdict{border-left:3px solid #ffb56d;background:#15302e;padding:18px 24px;margin:30px 0}.verdict strong{color:#f5dfbd}.verdict p{margin:6px 0}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin:26px 0}.stat{border-top:1px solid #b5dec337;padding:22px 0}.stat b{font-size:32px;display:block;color:#e9e8d4}.stat small{display:block;letter-spacing:1px;font-size:10px;color:#9ebbb0;margin-top:8px}h2{font-size:24px;margin:44px 0 20px;font-weight:500}.docs{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.doc{display:block;border:1px solid #b5dec32a;background:#10282a;padding:22px}.doc b{font-size:14px}.doc span{display:block;font-size:12px;line-height:1.6;color:#a9c1b5;margin-top:10px}.covers{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}figure{margin:0}figure img{display:block;width:100%;height:auto;border:1px solid #b5dec340}figcaption{font-size:12px;color:#b7c9c0;line-height:1.6;margin-top:12px}li{color:#b7c9c0;line-height:1.7;margin:8px 0}footer{margin-top:40px;padding-top:20px;border-top:1px solid #b5dec32a;font-size:11px;color:#8daaa0}@media(max-width:700px){main{padding:30px 20px}.docs,.covers{grid-template-columns:1fr}.stats{gap:8px}.stat b{font-size:27px}.stat small{font-size:8px}}</style></head><body><main><header><span class="kicker">THE CINDER COAST · SOURCE &amp; EVIDENCE</span><h1>EMBERFALL.<br><em>Open the field notes.</em></h1><p>Original browser action: Relic Run solo expedition with dash, grenades, relic captures, a Warden boss and extraction, alongside classic squad survival. Code-drawn gameplay, generated cinematic key art and synthesized audio. This handover preserves the source, requested documents, real public screenshots and measured QA limits.</p><div class="actions"><a class="button primary" href="emberfall-handover.zip" download>DOWNLOAD COMPLETE HANDOVER</a><a class="button" href="/">PLAY EMBERFALL</a></div></header><aside class="verdict"><strong>Relic Run upgrade is playable. Classic multiplayer launch gate remains open.</strong><p>Relic Run completed 1,000 input-driven automated runs with no invalid or stuck endings; browser preview observed firing, grenade use, dash, replay and solo pause. These tests do not establish human difficulty or physical-phone performance. Historical classic bot gameplay, training and host checkpoint recovery were observed. This cloud browser gathered zero WebRTC candidates, so shared combat, peer reconnect and live migration remain unverified. Physical-phone performance also needs validation. Bot-only median duration was 3:56, below the requested 8–12 minutes.</p></aside><div class="stats"><div class="stat"><b>34 / 34</b><small>UNIT &amp; REAL-SQL SERVICE TESTS PASSED</small></div><div class="stat"><b>1,000</b><small>FULL 20 HZ BOT MATCHES · ZERO FAILURES</small></div><div class="stat"><b>64</b><small>CONFIGURED COMBATANTS · UP TO 8 HUMANS</small></div></div><p><a href="evidence/adventure-soak.json">New Relic Run input-driven results</a> · <a href="evidence/action-upgrade.json">Action upgrade QA</a></p><h2>Six documents. Every trade-off on record.</h2><div class="docs">'''+links+'''</div><h2>Relic Run · real public gameplay.</h2><a href="relic-run-gameplay.jpg" download><img src="relic-run-gameplay.jpg" width="1363" height="936" style="width:100%;height:auto;border:1px solid #b5dec340" alt="Actual Relic Run raiders and a grenade in flight" loading="lazy"></a><p>Unedited public v13 capture. Grenade warnings, raiders and real inventory; no fabricated victory.</p><h2>Historical classic covers from the public game.</h2><div class="covers"><figure><a href="cover-1.png" download><img src="cover-1.png" width="1800" height="1200" alt="EMBERFALL live cinematic lobby" loading="lazy"></a><figcaption><a href="cover-1.png" download>cover-1.png</a> · Lobby, public v5.</figcaption></figure><figure><a href="cover-2.png" download><img src="cover-2.png" width="1800" height="1200" alt="Live combat with bot practice disclosed" loading="lazy"></a><figcaption><a href="cover-2.png" download>cover-2.png</a> · Live combat, public v11 bot practice with squad autopilot.</figcaption></figure><figure><a href="cover-3.png" download><img src="cover-3.png" width="1800" height="1200" alt="Finch 4 bot champions shown in explicitly labelled spectator view" loading="lazy"></a><figcaption><a href="cover-3.png" download>cover-3.png</a> · Actual bot champions in spectator view. The viewer was defeated.</figcaption></figure></div><p>All three are 1800 × 1200 browser screenshots. No mockups, composites, resized scenes or altered scores. Exact provenance and hashes are in ASSETS.md and the evidence folder.</p><h2>Checks that still need real devices and networks.</h2><ul><li>Two distinct guests sharing combat, peer refresh within 60 seconds, host migration and impaired real WebRTC traffic.</li><li>Android and iOS Safari touch, safe areas, fullscreen, audio, haptics, real 4G cold load and 4× CPU performance.</li><li>Eight concurrent networked matches and longer-play balance sessions. The current server-authority fallback trusts a peer host, uses external STUN and has no TURN relay.</li></ul><p><a href="evidence/soak-production.json">1,000-match raw results</a> · <a href="evidence/network-load.json">Synthetic impairment and simulation load</a> · <a href="evidence/browser-network.json">Observed RTC blocker</a> · <a href="evidence/browser-qa.json">Browser QA record</a> · <a href="manifest.json">Download checksum</a> · <a href="/qa/responsive.html">Responsive layout viewer</a></p><footer>Built with ChatGPT · 2026-10-29 · No purchases, ads or tracking. Vault Rush remains untouched.</footer></main></body></html>'''
(out/'index.html').write_text(html)
print(json.dumps(manifest,indent=2))
